<?php declare(strict_types=1);namespace App\Modules\Subcontracts\Controllers;use App\Core\Exceptions\BusinessRuleException;use App\Core\Exceptions\ValidationException;use App\Core\Http\Csrf;use App\Core\Http\Request;use App\Core\Http\Response;use App\Core\Http\Session;use App\Core\View\View;use App\Modules\Subcontracts\Services\SubcontractService;use App\Modules\Subcontracts\Validators\SubcontractValidator;final class SubcontractController{public function __construct(private readonly View$v,private readonly Csrf$csrf,private readonly Session$session,private readonly SubcontractService$s,private readonly SubcontractValidator$validator){}public function index(Request$r):Response{return Response::html($this->v->render('modules/subcontracts/index',['title'=>'عقود مقاولي الباطن','rows'=>$this->s->all()]));}public function create(Request$r):Response{return$this->form(null);}public function edit(Request$r):Response{return$this->form((int)$r->route('id'));}public function show(Request$r):Response{$x=$this->s->find((int)$r->route('id'));return Response::html($this->v->render('modules/subcontracts/show',['title'=>'تفاصيل عقد مقاول الباطن','subcontract'=>$x,'transitions'=>$this->s->transitions($x['status'])]));}public function store(Request$r):Response{return$this->save($r,null);}public function update(Request$r):Response{return$this->save($r,(int)$r->route('id'));}public function status(Request$r):Response{if(!$this->csrf->isValid($r->input('_token')))return Response::html('انتهت صلاحية الطلب.',419);$id=(int)$r->route('id');try{$this->s->change($id,(string)$r->input('status'));$this->flash('success','تم التحديث','تم تغيير الحالة.');}catch(BusinessRuleException$e){$this->flash('error','تعذر التحديث',$e->getMessage());}return Response::redirect("/subcontracts/$id");}private function form(?int$id):Response{return Response::html($this->v->render('modules/subcontracts/form',['title'=>$id?'تعديل عقد مقاول باطن':'إضافة عقد مقاول باطن','subcontract'=>$id?$this->s->find($id):null,...$this->s->refs()]));}private function save(Request$r,?int$id):Response{if(!$this->csrf->isValid($r->input('_token')))return Response::html('انتهت صلاحية الطلب.',419);try{$id=$this->s->save($this->validator->validate($r->all()),$id);return Response::redirect("/subcontracts/$id");}catch(ValidationException|BusinessRuleException$e){$this->flash('error','تعذر الحفظ',$e instanceof BusinessRuleException?$e->getMessage():'يرجى مراجعة البيانات.');return Response::redirect($id?"/subcontracts/$id/edit":'/subcontracts/create');}}private function flash(string$type,string$title,string$text):void{$this->session->flash('alert',compact('type','title','text'));}}
